CREATE FUNCTION public.workbench_apply_auto_checklist(p_rows jsonb) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ BEGIN INSERT INTO public.workbench_checklist(lead_id,item_key,label,status,source,note,updated_by) SELECT x.lead_id,x.item_key,x.label,x.status,'auto',x.note,auth.uid() FROM jsonb_to_recordset(p_rows) AS x(lead_id uuid,item_key text,label text,status text,note text) ON CONFLICT(lead_id,item_key) DO UPDATE SET label=excluded.label,status=excluded.status,note=excluded.note,updated_at=now() WHERE workbench_checklist.source='auto'; END $$; REVOKE ALL ON FUNCTION public.workbench_apply_auto_checklist(jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.workbench_apply_auto_checklist(jsonb) TO authenticated,service_role;